### Description

The combination of three different pydantic features can lead to inconsistent behaviour.
- `extra=allow`
- `@computed_field`
- `exclude=None`

This scenario arises when one pydantic object is serialized to create another pydantic object.
```python
some_object = Model(**another_object.model_dump())
```

With `extra=allow`, I think either an error should be raised or attempts to set a computed property be ignored. Instead both the static value and the computed property are kept. Different serializations reveal either the static value, or the computed property.

### Example Code

```Python
import pytest
from pydantic import BaseModel, computed_field, ConfigDict

class WorkingModel(BaseModel):
    name: str

    @computed_field
    def favorite_color(self) -> str:
        if self.name == 'John':
            return None
        return 'blue'

@pytest.fixture
def working_model():
    return WorkingModel(name='John', favorite_color='red')

def test_working_model_dump_exclude_none_with_john(working_model):
    result = working_model.model_dump(exclude_none=True)
    # favorite_color should be omitted because computed_field returns None for 'John'
    assert result == {'name': 'John'}

def test_working_model_dump_with_john_includes_computed_field(working_model):
    result = working_model.model_dump()
    # favorite_color should be included even if computed_field returns None
    assert result == {'name': 'John', 'favorite_color': None}

def test_working_model_dump_with_json(working_model):
    result = working_model.model_dump_json()
    assert result == '{"name":"John","favorite_color":null}'

def test_working_model_dump_exclude_none_with_richard(working_model):
    working_model.name = 'Richard'
    result = working_model.model_dump(exclude_none=True)
    # favorite_color should be 'blue' from computed_field for any name other than 'John'
    assert result == {'name': 'Richard', 'favorite_color': 'blue'}


class BrokenModel(WorkingModel):
    model_config = ConfigDict(extra='allow')

@pytest.fixture
def broken_model():
    return BrokenModel(name='John', favorite_color='red')

def test_broken_model_dump_exclude_none_with_john(broken_model):
    result = broken_model.model_dump(exclude_none=True)
    # E         Left contains 1 more item:
    # E         {'favorite_color': 'red'}
    assert result == {'name': 'John'}

def test_broken_model_dump(broken_model):
    result = broken_model.model_dump()
    assert result == {"name": "John", "favorite_color": None}

def test_broken_model_dump_with_json(broken_model):
    result = broken_model.model_dump_json()
    # E         - {"name": "John", "favorite_color": null}
    # E         + {"name":"John","favorite_color":"red","favorite_color":null}
    assert result == '{"name":"John","favorite_color":null}'

def test_broken_model_dump_with_john_includes_computed_field(broken_model):
    result = broken_model.model_dump()
    assert result == {'name': 'John', 'favorite_color': None}

def test_broken_model_dump_exclude_none_with_richard(broken_model):
    broken_model.name = 'Richard'
    result = broken_model.model_dump(exclude_none=True)
    assert result == {'name': 'Richard', 'favorite_color': 'blue'}
